# ChartForgeX core: Chart and ChartOptions.
# move  Type.Member -> Path [delete]   references become receiver.Path; the declaration moves into the type of Path's
#                                       parent (renamed to Path's last segment), or is deleted with "delete".
# call  Type.Method[(T1,T2)] -> template   call sites rewritten; declaration deleted.
# keep  Type.Method[(T1,T2)] -> NewName    declaration and call sites renamed (hand-written method stays).
# inline Type.Property                     the owner's fluent surface includes Property's methods.

inline Chart.Options

# --- Chart axis titles live on the axes -----------------------------------------------------------
move Chart.XAxisTitle -> Options.XAxis.Title delete
move Chart.YAxisTitle -> Options.YAxis.Title delete
move Chart.SecondaryYAxisTitle -> Options.SecondaryYAxis.Title delete
move Chart.SecondaryXAxisTitle -> Options.SecondaryXAxis.Title delete

