# --- Chart methods that are not plain setters ------------------------------------------------------
keep Chart.WithSize -> Size  # two numbers read better than new ChartSize(w, h); validates both
keep Chart.WithPadding -> Padding  # four sides in one call; validates each
call Chart.WithTheme -> Theme({theme}) ; [ThemeMode({mode:value})]
keep Chart.WithFontFamily -> FontFamily  # derives a new immutable theme
call Chart.WithPngFont(string?,int?,string?) -> Png.FontPath({fontPath}) ; [Png.FontCollectionIndex({collectionIndex})] ; [Png.FontFaceName({faceName})]
call Chart.WithPngFont(string?,string?) -> Png.FontPath({fontPath}) ; Png.FontFaceName({faceName})
call Chart.WithPngOutputScale(ChartPngOutputScale) -> Png.OutputScale((int){scale})
