call Chart.WithSecondaryXAxisScale -> SecondaryXAxis.Scale({scale})
call Chart.WithXAxisTimeScale -> XAxis.TimeScale([timeZone: {timeZone}], [showTimeZone: {showTimeZone}], [label: {label}])
call Chart.WithXAxisBounds -> XAxis.Bounds({minimum}, {maximum})
call Chart.WithYAxisBounds -> YAxis.Bounds({minimum}, {maximum})
call Chart.WithSecondaryYAxisBounds -> SecondaryYAxis.Bounds({minimum}, {maximum})
call Chart.WithSecondaryXAxisBounds -> SecondaryXAxis.Bounds({minimum}, {maximum})
call Chart.WithAutomaticXAxisBounds -> XAxis.Min(null) ; XAxis.Max(null)
call Chart.WithAutomaticYAxisBounds -> YAxis.Min(null) ; YAxis.Max(null)
call Chart.WithAutomaticSecondaryYAxisBounds -> SecondaryYAxis.Min(null) ; SecondaryYAxis.Max(null)
call Chart.WithAutomaticSecondaryXAxisBounds -> SecondaryXAxis.Min(null) ; SecondaryXAxis.Max(null)
call Chart.WithXAxisIntegerTicks -> XAxis.IntegerTicks([{enabled}])
call Chart.WithYAxisIntegerTicks -> YAxis.IntegerTicks([{enabled}])
call Chart.WithSecondaryYAxisIntegerTicks -> SecondaryYAxis.IntegerTicks([{enabled}])
