keep Chart.WithXDateLabels -> XDateLabels  # formats dates into category labels
keep Chart.WithAxes -> Axes  # switches four related flags (axes, both axis visibilities, axis lines) together
call Chart.WithTickCount -> TickCount({count})
call Chart.WithGrid -> ShowGrid([{visible}])
call Chart.WithGridStyle -> GridLineStyle({style})
call Chart.ConfigureGridStyle -> !GridLineStyle({configure})
call Chart.WithAxisLines -> ShowAxisLines([{visible}])
call Chart.WithHeader -> ShowHeader([{visible}])
call Chart.WithCard -> ShowCard([{visible}])
