call Chart.WithMapColorScale(ChartColor,ChartColor,ChartColor,double?) -> Map.ColorScale(ChartColorScale.Diverging({lowColor}, {midpointColor}, {highColor}[, {midpointValue}]))
call Chart.WithRegionMapBounds -> Map.RegionBounds({bounds})
keep Chart.WithRegionMapCoordinateBounds -> RegionMapCoordinateBounds  # converts longitude/latitude bounds and validates ranges
call Chart.WithPictorialValues -> Pictorial.ShowValues([{visible}])
call Chart.WithPictorialSvgPath(string,ChartPictorialShape) -> Pictorial.SvgPath({pathData}[, {pngFallbackShape}])
