call Chart.WithWordCloudFontRange -> WordCloud.FontRange({minimum}, {maximum})
call Chart.WithWordCloudMaximumTerms -> WordCloud.MaxTerms({maximumTerms})
keep Chart.WithGanttToday(DateTime?) -> GanttToday  # converts a DateTime to the schedule value
call Chart.WithGanttToday(double?) -> Gantt.Today({value})
keep Chart.WithGanttLaneNow -> GanttLaneNow  # converts a DateTime to the ordered schedule value
