call Chart.WithStateColorsPinnedInForcedColors -> StateTimeline.PinColorsInForcedColors([{pin}])
keep Chart.WithStateCategories -> StateCategories  # validates unique keys and replaces the category list
call Chart.WithAutomaticRadialBands -> RadialBandAllocation({allocation})
call Chart.WithRadialGeometry -> RadialGeometry({geometry})
call Chart.WithValueFormatter -> FormatValuesBy({formatter})
call Chart.WithValueFormat -> ValueFormat({format})
call Chart.WithValueUnit -> ValueUnit({unit})
keep Chart.WithCulture -> Culture  # applies a read-only culture copy to every axis
keep Chart.WithDesignTokens -> DesignTokens  # copies design tokens into a new immutable theme
call Chart.WithSvgColorVariables -> SvgColorVariables({variables})
call Chart.WithSeriesColorAssignment -> SeriesColorAssignment({assignment})
call Chart.WithMarkBackdrop -> MarkBackdrop({backdrop})
